    #[test]
    fn layout_stays_inside_minimum_and_4k_gui_sizes() {
        let (mut b, home) = browser();
        b.state.view.filters.max_ping = Some(100);
        b.state.view.filters.favorites = true;
        b.state.view.filters.not_full = true;
        for (w, h) in [
            (320.0, 240.0),
            (427.0, 240.0),
            (854.0, 480.0),
            (640.0, 360.0),
            (1920.0, 1080.0),
            (3840.0, 2160.0),
        ] {
            for modal in [
                Modal::Main,
                Modal::Settings,
                Modal::Filters(0),
                Modal::Filters(1),
                Modal::Sort,
                Modal::Edit {
                    index: None,
                    server: Box::default(),
                    tags: String::new(),
                    page: 0,
                },
                Modal::Feedback {
                    category: 0,
                    text: String::new(),
                },
            ] {
                b.modal = modal;
                let buttons = b.buttons((w, h));
                for (x, y, bw, _, _, _) in &buttons {
                    assert!(
                        *x >= 0.0 && *y >= 0.0 && x + bw <= w && y + 20.0 <= h,
                        "{w}x{h}: {x},{y},{bw}"
                    );
                }
                for (_, _, [x, y, fw, fh]) in b.form_fields((w, h)) {
                    assert!(x >= 0.0 && y >= 0.0 && x + fw <= w && y + fh <= h);
                }
                for (i, a) in buttons.iter().enumerate() {
                    for b in &buttons[i + 1..] {
                        assert!(
                            !(a.0 < b.0 + b.2
                                && a.0 + a.2 > b.0
                                && a.1 < b.1 + 20.0
                                && a.1 + 20.0 > b.1),
                            "overlapping buttons {:?} {:?}",
                            a,
                            b
                        );
                    }
                }
            }
        }
        drop(b);
        std::fs::remove_dir_all(home).unwrap();
    }
